import type { Pregunta } from '../quiz';

// Nivel INSTRUIDA (español) · 142 preguntas: autores, obras, leyes, artículos, fechas y distinciones finas.
// Convención: la PRIMERA opción es siempre la correcta (en pantalla se mezclan al azar).

export const instruida: Pregunta[] = [
  // ── El modelo ecológico ──
  { p: '¿Cuál de estos años NO corresponde a un hito del enfoque ecológico de la violencia?', o: ['1994', '1979', '1998', '2002'], e: '1994 es la Convención de Belém do Pará. 1979: Bronfenbrenner publica su teoría; 1998: Heise la aplica a la violencia contra las mujeres; 2002: la OMS la adopta en su Informe mundial.', f: 'El modelo ecológico recoge lo que plantean los principales acuerdos internacionales: la Declaración sobre la Eliminación de la Violencia contra la Mujer (Naciones Unidas, 1993), la Convención de Belém do Pará (1994), que la Argentina aprobó con la Ley 24.632, y la Declaración de Bogotá sobre ciudades seguras para mujeres y niñas (2004).', t: 'modelo-ecologico' },
  { p: '¿En qué documento adoptó la OMS el modelo ecológico de cuatro niveles?', o: ['El Informe mundial sobre la violencia y la salud (2002)', 'La Declaración sobre la Eliminación de la Violencia contra la Mujer (1993)', 'La Convención de Belém do Pará (1994)', 'La Declaración de Bogotá sobre ciudades seguras (2004)'], e: 'En el Informe mundial sobre la violencia y la salud (2002). Los otros son instrumentos que el modelo recoge, pero no lo formulan.', f: 'La Organización Mundial de la Salud adoptó este enfoque en su Informe mundial sobre la violencia y la salud (2002), con cuatro niveles.', t: 'modelo-ecologico' },
  { p: 'Impunidad, acceso fácil a armas y corrupción, cuando se vuelven costumbre, funcionan como un “capital social negativo”. ¿En qué nivel?', o: ['Social o macrosocial', 'Comunitario o mesosocial', 'Histórico o cronosistema', 'Relacional o microsocial'], e: 'Son factores de la estructura de toda la sociedad: nivel social o macrosocial. El comunitario mira el barrio, la escuela y el trabajo; el histórico, cómo cambian las cosas con el tiempo.', f: 'Cuando estos factores se vuelven costumbre, funcionan como un “capital social negativo o anómico”: un clima que favorece la violencia y la desobediencia a la ley.', t: 'modelo-ecologico' },
  { p: '¿Qué sistema sumó Bronfenbrenner en 1986, y que esta guía usa como quinto nivel?', o: ['El cronosistema: el momento histórico', 'El exosistema: lugares donde la persona no está, pero que la afectan', 'El mesosistema: la conexión entre los microsistemas', 'El macrosistema: la cultura, las creencias y las leyes'], e: 'El cronosistema (1986). Microsistema, mesosistema, exosistema y macrosistema ya estaban en la obra de 1979.', f: 'Cronosistema: el momento histórico.', t: 'modelo-ecologico' },
  { p: 'Hace unas décadas, la violencia en la pareja se veía como un “asunto privado”; hoy la ley la reconoce como violación de derechos. ¿Qué nivel del modelo describe ese cambio?', o: ['El histórico', 'El social', 'El comunitario', 'El relacional'], e: 'Es un cambio de época: nivel histórico o cronosistema. El nivel social describe la cultura y las leyes de un momento; el histórico, cómo cambian con el tiempo.', f: 'Esta guía agrega un quinto nivel, el histórico (el cronosistema de Bronfenbrenner): cada época le da a la violencia un sentido distinto, y en cada momento ciertas ideologías violentas tienen más o menos fuerza.', t: 'modelo-ecologico' },
  { p: '¿Qué es cada una de estas normas: el Decreto 1011/2010 y la Ley 24.632?', o: ['El decreto reglamenta la Ley 26.485; la ley aprueba Belém do Pará', 'Las dos modificaron la Ley 26.485 para sumar nuevas modalidades', 'El decreto aprueba Belém do Pará; la ley reglamenta la Ley 26.485', 'Las dos aprueban convenciones internacionales sobre las mujeres'], e: 'El Decreto 1011/2010 reglamenta la Ley 26.485, y la Ley 24.632 (1996) aprueba la Convención de Belém do Pará.', f: 'En el país, se refleja en la Ley 26.485 y su decreto reglamentario 1011/2010, que piden intervenir de manera integral, con distintos organismos a la vez (ver Legislación).', t: 'modelo-ecologico' },

  // ── Violencia de género ──
  { p: 'En la Ley 26.485, ¿qué diferencia hay entre el art. 5 y el art. 6?', o: ['El 5 enumera los tipos; el 6, las modalidades', 'El 5 enumera las modalidades; el 6, los tipos', 'El 5 define la violencia; el 6 enumera sus tipos', 'El 5 enumera los tipos; el 6, los derechos'], e: 'El art. 4 define la violencia, el 5 enumera los tipos y el 6 las modalidades.', f: 'Las modalidades dicen dónde o en qué ámbito ocurre la violencia.', t: 'violencia-de-genero' },
  { p: '¿Qué sumaron a la Ley 26.485 las leyes 27.501 y 27.533, ambas de 2019?', o: ['La violencia en el espacio público y la violencia política', 'La violencia digital y la violencia mediática', 'La violencia obstétrica y contra la libertad reproductiva', 'El femicidio y el travesticidio como agravantes'], e: 'La 27.501 sumó la modalidad en el espacio público y la 27.533, la violencia política. La digital llegó en 2023 (Ley 27.736) y el femicidio está en el Código Penal (Ley 26.791).', f: 'La incorporó la Ley 27.501 (2019).', t: 'violencia-de-genero' },
  { p: '¿Con qué leyes se vinculan las modalidades obstétrica y contra la libertad reproductiva, en ese orden?', o: ['25.929 y 25.673', '25.673 y 25.929', '26.061 y 25.673', '25.929 y 26.150'], e: 'Obstétrica: Ley 25.929 de Parto Humanizado. Libertad reproductiva: Ley 25.673 de Salud Sexual y Procreación Responsable.', f: 'Contra la libertad reproductiva: la que vulnera el derecho a decidir cuántos hijos tener y cuándo (Ley 25.673).', t: 'violencia-de-genero' },
  { p: 'Además de los organismos públicos, ¿dónde puede darse violencia institucional según el art. 6?', o: ['En partidos políticos, sindicatos y entidades deportivas', 'En medios de comunicación y agencias de publicidad', 'En clínicas, sanatorios y hospitales de gestión privada', 'En escuelas, institutos y universidades privadas'], e: 'La ley incluye partidos, sindicatos, organizaciones empresariales, deportivas y de la sociedad civil. Lo que ocurre en los medios es violencia mediática.', f: 'Incluye también a partidos políticos, sindicatos, organizaciones empresariales y deportivas.', t: 'violencia-de-genero' },
  { p: '¿Cuál de estas afirmaciones sobre la Ley Olimpia es correcta?', o: ['Es la Ley 27.736 y sumó la violencia digital a la Ley 26.485', 'Es una ley mexicana a la que la Argentina adhirió por tratado', 'Es la Ley 27.501 y sumó el acoso callejero a la Ley 26.485', 'Se aplica a la violencia digital entre parejas o exparejas'], e: 'La Ley 27.736 (2023) sumó la violencia digital. Lleva el nombre de Olimpia Coral Melo, que impulsó leyes similares en México, y no se limita a parejas.', f: 'En 2023, la Ley 27.736, conocida como Ley Olimpia, sumó la violencia digital a la Ley 26.485.', t: 'violencia-de-genero' },
  { p: '¿Qué hizo la Ley 26.791, de 2012?', o: ['Incorporó el femicidio al art. 80 del Código Penal, con prisión perpetua', 'Definió los tipos y las modalidades de violencia contra las mujeres', 'Aprobó en la Argentina la Convención de Belém do Pará', 'Creó el registro nacional de femicidios de la Corte Suprema'], e: 'La 26.791 incorporó el femicidio al art. 80 del Código Penal. Los tipos y modalidades están en la Ley 26.485, y Belém do Pará se aprobó con la Ley 24.632.', f: 'Desde 2012, el Código Penal castiga el femicidio con prisión perpetua (Ley 26.791, que lo incorporó al art. 80).', t: 'violencia-de-genero' },

  // ── Ciclo de la violencia ──
  { p: '¿Quién describió el ciclo de la violencia y quién el control coercitivo?', o: ['Lenore Walker (1979) y Evan Stark (2007)', 'Evan Stark (1979) y Lenore Walker (2007)', 'Lenore Walker (1979) y Lori Heise (1998)', 'Lori Heise (1998) y Evan Stark (2007)'], e: 'Walker describió el ciclo en The Battered Woman (1979) y Stark, el control coercitivo (2007). Heise propuso el enfoque ecológico de la violencia (1998).', f: 'El sociólogo Evan Stark (2007) lo llamó control coercitivo: vigilar el celular, decidir con quién puede verse, manejar todo el dinero, controlar cómo se viste, amenazar, aislar.', t: 'ciclo-de-la-violencia' },
  { p: 'En el modelo original de Walker, ¿cómo se llama la etapa de arrepentimiento y cariño que sigue al estallido?', o: ['Luna de miel', 'Temor a perder la relación', 'Post-explosión', 'Reconciliación'], e: 'En el original es la luna de miel. La versión de cuatro fases la llama temor a perder la relación y reserva luna de miel para la calma. Post-explosión es una fase del ciclo de agresión del enojo.', f: 'En el modelo original de Walker hay tres fases: acumulación de tensión, estallido y “luna de miel”, que es el arrepentimiento y el cariño que llegan después.', t: 'ciclo-de-la-violencia' },
  { p: 'En la versión de cuatro fases, ¿qué fase sigue inmediatamente al período violento?', o: ['Temor a perder la relación', 'Período de luna de miel', 'Post-explosión', 'Acumulación de tensión'], e: 'Después del estallido llegan el arrepentimiento y las promesas (temor a perder la relación), y recién después la luna de miel.', f: 'La versión de cuatro fases que usamos acá, muy difundida, separa ese arrepentimiento (“temor a perder la relación”) de la calma que viene después (“luna de miel”).', t: 'ciclo-de-la-violencia' },
  { p: 'El control coercitivo sin golpes, ¿como qué tipos de violencia lo reconoce la Ley 26.485?', o: ['Psicológica y económica', 'Simbólica y mediática', 'Doméstica e institucional', 'Física y sexual'], e: 'Vigilar, aislar y controlar el dinero son violencia psicológica y económica. Doméstica e institucional son modalidades, no tipos; mediática también es una modalidad.', f: 'Aunque no haya golpes, es violencia, y la Ley 26.485 la reconoce como violencia psicológica y económica.', t: 'ciclo-de-la-violencia' },

  // ── Efectos de la violencia de género en las infancias ──
  { p: '¿Quiénes definieron el "trauma relacional"?', o: ['Sheinberg y True (2008)', 'Fernández-Montalvo y Echeburúa (1997)', 'Grosman y Mesterman', 'Walker y Barton (1983)'], e: 'Sheinberg y True (2008), en la revista Family Process: la seguridad del vínculo, quebrada por las mismas personas adultas que deberían darla.', f: 'Sheinberg y True (2008), en un trabajo publicado en la revista de terapia familiar Family Process, llaman a esto trauma relacional: la ruptura de la seguridad emocional o física que debería dar el vínculo con madres, padres o personas cuidadoras, causada por esas mismas personas adultas.', t: 'efectos-en-las-infancias' },
  { p: '¿Qué médico forense advirtió que la sociedad no ve lo importante que es tener en cuenta a hijas e hijos en la violencia de género?', o: ['Miguel Lorente Acosta', 'Herrezuelo Sáez', 'José Garriga Zucal', 'Marcela Lagarde'], e: 'Miguel Lorente Acosta (2001), autor de Mi marido me pega lo normal.', f: 'El médico forense Miguel Lorente Acosta (2001) advierte que la sociedad no ve lo importante que es tenerlos en cuenta.', t: 'efectos-en-las-infancias' },
  { p: '¿Qué autor propone evaluar el tipo de violencia, la protección del entorno, el vínculo con la madre y los recursos de cada niño?', o: ['Jorge Barudy (1998)', 'Lenore Walker (1979)', 'Lori Heise (1998)', 'Aaron Beck (1979)'], e: 'Barudy, en El dolor invisible de la infancia (1998).', f: 'Por eso, para evaluar el riesgo, el psiquiatra Jorge Barudy (1998) propone mirar el tipo y la frecuencia de la violencia, la protección que brinda el entorno, el vínculo con la madre (y el apoyo que ella misma recibe), la edad y los recursos propios de cada niña o niño.', t: 'efectos-en-las-infancias' },
  { p: '¿Qué ley argentina consagra el interés superior del niño citado en el tema?', o: ['La Ley 26.061', 'La Ley 26.485', 'La Ley 23.515', 'La Ley 26.618'], e: 'La Ley 26.061 de Protección Integral de los Derechos de Niñas, Niños y Adolescentes.', f: 'Se guía por el interés superior del niño (Ley 26.061): no suspende el contacto con el padre denunciado de forma automática, sino según la gravedad de cada caso, y lo sostiene si hay un buen vínculo comprobado.', t: 'efectos-en-las-infancias' },
  { p: '¿Qué observan Fernández-Montalvo y Echeburúa (1997) sobre quienes crecieron con violencia?', o: ['Pocos la ejercen, pero quedan más vulnerables', 'La mayoría la repite en la adultez', 'No muestran consecuencias a largo plazo', 'La repiten sobre todo como víctimas'], e: 'Pocas de esas personas ejercen maltrato en la adultez, aunque sí quedan más vulnerables.', f: 'Fernández-Montalvo y Echeburúa (1997) observan que pocas personas que crecieron con violencia la ejercen en la adultez, aunque sí quedan más vulnerables.', t: 'efectos-en-las-infancias' },
  { p: 'Mojar la cama y no controlar la evacuación, cuando ya se había logrado, se llaman…', o: ['Enuresis y encopresis', 'Disociación y parentalización', 'Ansiedad y regresión', 'Insomnio y fobia'], e: 'Son conductas regresivas: enuresis (orina) y encopresis (evacuación).', f: 'Por ejemplo, volver a mojar la cama (enuresis) o no controlar la evacuación (encopresis) cuando ya lo habían logrado, o pedir de nuevo el chupete o hablar “como bebé”.', t: 'efectos-en-las-infancias' },

  // ── Igualdad y no discriminación ──
  { p: '¿Qué capítulo del Compendio de la CIDH desarrolla la obligación reforzada de proteger a grupos en situación de vulnerabilidad?', o: ['El capítulo 4', 'El capítulo 2', 'El capítulo 7', 'El capítulo 1'], e: 'El capítulo 4: el principio de igualdad y no discriminación implica una obligación reforzada.', f: 'Según la CIDH, los Estados tienen una obligación reforzada: deben hacer un esfuerzo mayor para proteger a los grupos en situación de vulnerabilidad.', t: 'igualdad-y-no-discriminacion' },
  { p: '¿Qué concepto usa el sistema interamericano cuando confluyen varios factores de vulnerabilidad?', o: ['Interseccionalidad', 'Transversalidad', 'Debida diligencia', 'Revictimización'], e: 'La interseccionalidad. La transversalidad es un precepto de la Ley 26.485 y la debida diligencia, una obligación de los Estados.', f: 'La Comisión Interamericana de Derechos Humanos (CIDH) usa el concepto de interseccionalidad para analizar los casos en los que se cruzan varias condiciones que aumentan el riesgo de ser discriminada.', t: 'igualdad-y-no-discriminacion' },
  { p: '¿Qué organismo elabora el Registro Nacional de Femicidios de la Justicia Argentina?', o: ['La Oficina de la Mujer de la Corte Suprema', 'El Observatorio de Crímenes de Odio LGBT+', 'El Comité de la CEDAW de Naciones Unidas', 'La Comisión Interamericana de Derechos Humanos'], e: 'La Oficina de la Mujer de la Corte Suprema de Justicia de la Nación.', f: 'Según el Registro Nacional de Femicidios de la Justicia Argentina, que elabora la Oficina de la Mujer de la Corte Suprema, en 2025 hubo 200 víctimas directas de femicidio (incluidas mujeres trans y travestis): una cada 44 horas, la cifra más baja desde 2017.', t: 'igualdad-y-no-discriminacion' },
  { p: 'Según el Registro Nacional de Femicidios, ¿cuántas víctimas directas de femicidio hubo en la Argentina en 2025?', o: ['200', '227', '346', '204'], e: '200: una cada 44 horas, la cifra más baja desde 2017. 227 son los crímenes de odio LGBT+ de 2025, 346 las víctimas del fútbol que registra Salvemos al Fútbol y 204 los adultos del experimento de Condry y Condry.', f: 'Según el Registro Nacional de Femicidios de la Justicia Argentina, que elabora la Oficina de la Mujer de la Corte Suprema, en 2025 hubo 200 víctimas directas de femicidio (incluidas mujeres trans y travestis): una cada 44 horas, la cifra más baja desde 2017.', t: 'igualdad-y-no-discriminacion' },
  { p: 'Según el Cap. II de la Ley 26.485, el organismo competente celebra convenios para…', o: ['Rehabilitar a los hombres que ejercen violencia', 'Mediar entre la mujer y quien la agredió', 'Crear juzgados especiales en cada provincia', 'Dar asistencia legal gratuita a ambas partes'], e: 'Convenios de prevención, asistencia a las mujeres y rehabilitación de los hombres que ejercen violencia. La mediación está expresamente excluida.', f: 'El organismo nacional encargado de aplicar la ley debe coordinar con las provincias y con organizaciones especializadas tareas de prevención, de asistencia a las mujeres y de trabajo con los varones que ejercen violencia.', t: 'igualdad-y-no-discriminacion' },
  { p: 'Según la CEDAW, la discriminación contra la mujer puede darse por objeto o por…', o: ['Resultado', 'Intención', 'Costumbre', 'Omisión'], e: '“Por objeto o por resultado”: no hace falta que haya intención de discriminar.', f: 'Para que haya discriminación no hace falta querer discriminar: alcanza con que el resultado le quite derechos a alguien.', t: 'igualdad-y-no-discriminacion' },

  // ── Legislación ──
  { p: 'Según la guía, ¿con qué años se identifica a la CEDAW?', o: ['1979 y 1981', '1994 y 1996', '1993 y 2004', '2009 y 2010'], e: 'La guía la fecha en 1979/1981. 1994 es Belém do Pará y 1996, su aprobación en Argentina por la Ley 24.632.', f: 'La Convención sobre la eliminación de todas las formas de discriminación contra la mujer fue aprobada por la Asamblea General de las Naciones Unidas el 18 de diciembre de 1979 y empezó a regir el 3 de septiembre de 1981.', t: 'legislacion' },
  { p: '¿Qué ley incorporó a la Ley 26.485 los derechos y bienes digitales de las mujeres?', o: ['La Ley 27.736 (2023)', 'La Ley 26.791 (2012)', 'La Ley 24.632 (1996)', 'La Ley 26.743 (2012)'], e: 'La Ley 27.736, de octubre de 2023, sustituyó el art. 4 y agregó el espacio digital.', f: 'h) Los derechos y bienes digitales de las mujeres, así como su desenvolvimiento y permanencia en el espacio digital (incorporado por Ley 27.736, 2023).', t: 'legislacion' },
  { p: 'En el texto de la Ley 26.485, ¿qué organismo figura como competente?', o: ['El Consejo Nacional de la Mujer', 'El Ministerio de Justicia de la Nación', 'La Defensoría del Pueblo de la Nación', 'La Comisión Interamericana de DD. HH.'], e: 'El art. 9 menciona al Consejo Nacional de la Mujer y sus funciones, como el Plan Nacional de Acción.', f: 'El organismo competente (la ley original nombra al Consejo Nacional de la Mujer; el organismo cambió de nombre y de rango varias veces) deberá, entre otras funciones:', t: 'legislacion' },
  { p: '¿Qué precepto rector del art. 7 de la Ley 26.485 exige articular entre instituciones y coordinar presupuestos?', o: ['La transversalidad', 'La interseccionalidad', 'La debida diligencia', 'La confidencialidad'], e: 'Es el principio de transversalidad (inc. d). La confidencialidad es otro precepto (inc. f).', f: 'd) La adopción del principio de transversalidad en todas las medidas y en la ejecución de las disposiciones normativas, articulando interinstitucionalmente y coordinando recursos presupuestarios.', t: 'legislacion' },
  { p: '¿Qué agrava el inciso 12 del art. 80 del Código Penal?', o: ['Matar para hacer sufrir a una pareja o expareja', 'Matar por odio a la identidad de género', 'Matar a la pareja o expareja, conviva o no', 'Matar a una mujer mediando violencia de género'], e: 'Agrava matar “con el propósito de causar sufrimiento” a una persona con la que se mantiene o ha mantenido una relación de pareja (inc. 1). Las otras opciones son los incisos 4, 1 y 11.', f: 'Con el propósito de causar sufrimiento a una persona con la que se mantiene o ha mantenido una relación en los términos del inciso 1°.', t: 'legislacion' },
  { p: '¿Qué pena establece el art. 80 del Código Penal para los homicidios agravados?', o: ['Reclusión o prisión perpetua', 'Prisión o reclusión de 8 a 25 años', 'Prisión de 3 a 15 años y multa', 'Multa e inhabilitación especial'], e: 'Reclusión o prisión perpetua. De 8 a 25 años es la atenuación posible en el inc. 1, que no se aplica si antes hubo violencia contra la mujer víctima.', f: 'Incorpora el femicidio y otras agravantes del homicidio, con pena de reclusión o prisión perpetua.', t: 'legislacion' },
  { p: '¿Qué tres ámbitos enumera el art. 2 de la Convención de Belém do Pará?', o: ['Familia, comunidad y Estado', 'Pareja, trabajo y escuela', 'Hogar, calle y medios', 'Ámbito privado, público y digital'], e: 'Comprende la violencia física, sexual y psicológica en la familia, en la comunidad y la perpetrada o tolerada por el Estado. El espacio digital lo incorporó la Ley 27.736 a la Ley 26.485, no Belém do Pará.', f: 'Art. 2 (síntesis): comprende la violencia física, sexual y psicológica en la familia, en la comunidad y la perpetrada o tolerada por el Estado.', t: 'legislacion' },
  { p: '¿Qué reconoce el art. 6 de la Convención de Belém do Pará?', o: ['No ser discriminada y educarse sin estereotipos', 'Recibir asistencia gratuita en servicios del Estado', 'Acceder a un cupo en la administración pública', 'Registrar la identidad de género en los documentos'], e: 'El derecho a ser libre de toda discriminación y a una educación sin patrones estereotipados.', f: 'Art. 6 (síntesis): derecho a ser libre de discriminación y a una educación sin patrones estereotipados.', t: 'legislacion' },

  // ── Micromachismos ──
  { p: '¿Qué pueblos estudiaron Godelier y Bourdieu para entender la dominación masculina en lo cotidiano?', o: ['Los baruya y los cabileños', 'Los mapuches y los qom', 'Los inuit y los pueblos sami', 'Los guaraníes y los quechuas'], e: 'Godelier estudió a los baruya de Nueva Guinea, y Bourdieu, a los cabileños, un pueblo bereber de Argelia.', f: 'Bonino se apoyó en estudios de antropología y sociología: los de Maurice Godelier sobre los baruya de Nueva Guinea y los de Pierre Bourdieu sobre los cabileños de Argelia.', t: 'micromachismos' },
  { p: 'Además de “micromachismos”, ¿qué nombre les dieron otros autores a conductas parecidas?', o: ['Pequeñas tiranías', 'Mística masculina', 'Capital social anómico', 'Muerte espiritual'], e: 'También se los llamó violencia “blanda”, machismo invisible o sexismo benévolo. Las otras expresiones son de Coontz, del modelo ecológico y de Holloway.', f: 'Otros autores llamaron a estas conductas “pequeñas tiranías”, “violencia blanda”, “machismo invisible” o “sexismo benévolo”.', t: 'micromachismos' },
  { p: 'Según Bonino, ¿qué poder, el de cuidar y sostener a otras personas, se les reconoció tradicionalmente a las mujeres?', o: ['El heteroafirmativo', 'El autoafirmativo', 'El de dominio', 'El coercitivo'], e: 'El poder heteroafirmativo. El autoafirmativo es la capacidad de hacer y decidir con autonomía; el de dominio controla la vida de otros.', f: 'Poder heteroafirmativo: el poder de cuidar y sostener a otras personas.', t: 'micromachismos' },
  { p: '¿Qué micromachismo encubierto consiste en creer que uno no tiene que dar explicaciones, pero exigírselas a los demás?', o: ['La inocentización', 'La seudonegociación', 'El aislamiento', 'El ninguneo'], e: 'La inocentización: el varón se ubica como juez y nunca como responsable. El aislamiento y el ninguneo son formas de crear falta de intimidad.', f: 'Él siempre es el juez y nunca el responsable.', t: 'micromachismos' },
  { p: 'Un varón inventa excusas para no hacer las tareas compartidas y bloquea los reclamos. ¿Qué micromachismo es?', o: ['Autoindulgencia y autojustificación', 'Inocentización culpabilizadora', 'Seudonegociación', 'Aislamiento y mal humor manipulativo'], e: 'Es una forma de inocentización: excusas que bloquean reclamos justos. La culpabilizadora, en cambio, juzga a la mujer por no cumplir su “rol tradicional”; el aislamiento y el mal humor manipulativo crean falta de intimidad.', f: 'Autojustificarse: dar excusas para no hacer su parte (“estoy cansado”, “vos lo hacés mejor”), y así bloquear reclamos justos.', t: 'micromachismos' },
  { p: 'Según Bonino, ¿cuándo aparecen los micromachismos de crisis?', o: ['Cuando cambia el equilibrio de poder en la pareja', 'Cuando él delega en ella las tareas del hogar', 'Cuando él abusa de la confianza y la credibilidad de ella', 'Cuando él usa la fuerza moral para imponerse'], e: 'Cuando el statu quo desigual se desequilibra, por más poder de ella o menos poder de él. Las otras opciones describen utilitarios, encubiertos y coercitivos.', f: 'Aparecen cuando la relación desigual empieza a cambiar: porque ella gana más autonomía (consigue trabajo, empieza a estudiar, pone límites) o porque él pierde poder (se queda sin trabajo, se enferma).', t: 'micromachismos' },

  // ── Mitos del amor romántico y celos ──
  { p: '¿Qué autores cita la guía para la teoría de la socialización diferencial?', o: ['Walker y Barton (1983)', 'Sheinberg y True (2008)', 'Main y Solomon (1990)', 'McKay y Davis (1981)'], e: 'Walker y Barton (1983): desde la infancia se aprenden identidades distintas según el género.', f: 'Según la teoría de la socialización diferencial (Walker y Barton, 1983), ese aprendizaje no es igual para todos: se nos enseñan identidades distintas según el género, con formas de pensar, sentir y actuar asignadas a cada uno.', t: 'mitos-del-amor-romantico' },
  { p: '¿Qué autora estudió cómo los cuentos, las películas y las canciones nos "seducen" con un ideal de pareja?', o: ['Coral Herrera', 'Marcela Lagarde', 'Esther Perel', 'Lenore Walker'], e: 'Coral Herrera, en La construcción sociocultural del amor romántico.', f: 'La investigadora Coral Herrera explica que los cuentos, las películas, las novelas y las canciones moldean lo que esperamos del amor: nos “seducen” con un ideal de pareja que parece perfecto, pero que tiene mucho de trampa.', t: 'mitos-del-amor-romantico' },
  { p: '¿Quién señaló que a las mujeres se les enseñó a sentirse completas solo al "pertenecer" a alguien o ser madres?', o: ['Marcela Lagarde (2000)', 'Coral Herrera', 'Esther Perel (2006)', 'Herrezuelo Sáez (2013)'], e: 'Marcela Lagarde, en Claves feministas para la autoestima de las mujeres (2000).', f: 'Según la antropóloga Marcela Lagarde (2000), incluso a sentirse completas solo cuando “pertenecen” a alguien o cuando son madres.', t: 'mitos-del-amor-romantico' },
  { p: '¿Qué autora plantea que cada pareja define sus propias reglas, además de las que toma de su cultura?', o: ['Esther Perel (2006)', 'Marcela Lagarde (2000)', 'Coral Herrera', 'Mary Ainsworth (1978)'], e: 'Esther Perel, en Mating in Captivity (2006).', f: 'Toda pareja define sus propias reglas, además de las que toma de su cultura (Perel, 2006).', t: 'mitos-del-amor-romantico' },
  { p: '¿Quién relacionó los mitos del amor romántico con la dificultad de salir de una relación violenta?', o: ['Herrezuelo Sáez (2013)', 'Stephen Mitchell (2002)', 'Esther Perel (2006)', 'Lori Heise (1998)'], e: 'Herrezuelo Sáez (2013), en un trabajo de la Universitat de les Illes Balears.', f: 'Sostiene la esperanza de que “va a cambiar”, y así hace más difícil salir de una relación violenta o pedir ayuda (Herrezuelo Sáez, 2013; ver El ciclo de la violencia).', t: 'mitos-del-amor-romantico' },
  { p: 'Según la guía, ¿qué suele haber detrás de los celos?', o: ['Miedo al abandono y sentirse poco valioso', 'Mucho amor y deseo de cuidar', 'Una infidelidad en la pareja actual', 'Una personalidad segura y dominante'], e: 'Detrás de los celos suele haber miedo al abandono y baja valoración propia, no exceso de amor ni necesariamente una infidelidad.', f: 'el miedo al abandono o a la traición', t: 'mitos-del-amor-romantico' },

  // ── Patriarcado y masculinidades ──
  { p: '¿Cómo se titula el libro de Terry Real citado en la guía?', o: ['“No quiero hablar de ello”', '“La masculinidad está matando a los hombres”', '“La mística masculina”', '“Sé un hombre”'], e: '“No quiero hablar de ello” (1997). “La masculinidad está matando a los hombres” es de Kali Holloway (2015).', f: 'El terapeuta familiar estadounidense Terry Real, en su libro No quiero hablar de ello (1997), muestra que el aprendizaje de “ser hombre” empieza mucho antes de lo que creemos:', t: 'patriarcado-y-masculinidades' },
  { p: '¿En qué año publicó Terry Real “No quiero hablar de ello”?', o: ['1997', '2015', '1979', '1998'], e: '1997. 2015 es el texto de Holloway, 1979 el de Walker y 1998 el de Heise.', f: 'El terapeuta familiar estadounidense Terry Real, en su libro No quiero hablar de ello (1997), muestra que el aprendizaje de “ser hombre” empieza mucho antes de lo que creemos:', t: 'patriarcado-y-masculinidades' },
  { p: '¿Quién escribió “La masculinidad está matando a los hombres” (2015)?', o: ['Kali Holloway', 'Stephanie Coontz', 'Marvin Allen', 'Klaudio Duarte'], e: 'Kali Holloway. Coontz habló de “mística masculina”, Allen del código masculino y Duarte de que el machismo se aprende.', f: 'La periodista estadounidense Kali Holloway (2015) dice que una de las frases más dañinas que puede escuchar un chico es “sé un hombre”.', t: 'patriarcado-y-masculinidades' },
  { p: 'Según la guía, ¿cuántos asesinatos vio en pantalla un varón de EE. UU. al llegar a los 18 años?', o: ['Unos 26.000', 'Unos 2.600', 'Unos 260.000', 'Unos 6.000'], e: 'Unos 26.000, la mayoría cometidos por hombres: así se transmite cómo “deberían” ser.', f: 'Holloway cita que, en los Estados Unidos, un chico de 18 años ya vio en pantalla unos 26.000 asesinatos, la mayoría cometidos por varones.', t: 'patriarcado-y-masculinidades' },
  { p: 'Según la guía, ¿qué porcentaje de los asesinatos cometen los hombres en EE. UU.?', o: ['El 90,5 %', 'El 76,8 %', 'El 80 %', 'El 63 %'], e: 'Cometen el 90,5 % y son el 76,8 % de las víctimas. El 80 % es la proporción de varones entre las personas que mueren por suicidio en la Argentina, y el 63 %, la de travestis y mujeres trans entre las víctimas de crímenes de odio LGBT+ en 2025.', f: 'Según los datos de los Estados Unidos que cita Holloway, los varones cometen el 90,5 % de los homicidios y también son el 76,8 % de las víctimas.', t: 'patriarcado-y-masculinidades' },
  { p: 'Según los datos de EE. UU. que cita Holloway, ¿qué porcentaje de las víctimas de homicidio son varones?', o: ['El 76,8 %', 'El 90,5 %', 'El 50,2 %', 'El 63,4 %'], e: 'Los varones son el 76,8 % de las víctimas y cometen el 90,5 % de los homicidios: el mandato de violencia también los daña a ellos.', f: 'los varones cometen el 90,5 % de los homicidios y también son el 76,8 % de las víctimas', t: 'patriarcado-y-masculinidades' },

  // ── Violencia en el fútbol ──
  { p: '¿Quién escribió Haciendo amigos a las piñas (2007)?', o: ['José Garriga Zucal', 'Pablo Alabarces', 'Jorge Barudy', 'Raymond Firth'], e: 'Garriga Zucal estudió la violencia y las redes sociales de una hinchada de fútbol.', f: 'El sociólogo Pablo Alabarces (2004) y el antropólogo José Garriga Zucal (2007) señalan tres ideas equivocadas que suelen aparecer cuando se habla de este tema:', t: 'violencia-en-el-futbol' },
  { p: '¿Qué libro de Pablo Alabarces (2004) se cita en el tema?', o: ['Crónicas del aguante', 'Haciendo amigos a las piñas', 'El dolor invisible de la infancia', 'Mi marido me pega lo normal'], e: 'Crónicas del aguante: fútbol, violencia y política (2004).', f: 'El sociólogo Pablo Alabarces (2004) y el antropólogo José Garriga Zucal (2007) señalan tres ideas equivocadas que suelen aparecer cuando se habla de este tema:', t: 'violencia-en-el-futbol' },
  { p: 'Según Garriga Zucal, "aguante" puede significar…', o: ['Alentar o pelear, según el caso', 'Pelear contra la policía', 'Alentar desde la tribuna', 'Viajar a todos los partidos'], e: 'Tiene distintos sentidos: alentar sin parar en la tribuna, o pelear.', f: 'La palabra tiene distintos sentidos según quién la use: puede ser alentar sin parar en la tribuna, viajar a todos lados para ver al equipo, o pelear contra la hinchada rival.', t: 'violencia-en-el-futbol' },
  { p: '¿Con qué actor propone trabajar especialmente el tema?', o: ['Con los medios de comunicación', 'Con las barras bravas', 'Con las fuerzas de seguridad', 'Con los jugadores'], e: 'Propone trabajar con todos los actores (funcionarios, periodistas, jugadores, familias y jóvenes), y especialmente con los medios.', f: 'Trabajar con todos los actores: funcionarios, dirigentes, periodistas, jugadores, familias y jóvenes, y especialmente con los medios de comunicación, que tienen un papel clave en cómo se cuenta la violencia.', t: 'violencia-en-el-futbol' },
  { p: '¿Qué propone la guía sobre las fuerzas de seguridad?', o: ['Profesionalizarlas para no agravar la violencia', 'Retirarlas de todos los estadios del país', 'Duplicar su número en todas las canchas', 'Dejar toda la prevención en sus manos'], e: 'Profesionalizarlas, para que intervengan sin agravar la violencia.', f: 'Profesionalizar a las fuerzas de seguridad, para que intervengan sin agravar la violencia por falta de preparación.', t: 'violencia-en-el-futbol' },
  { p: 'Según el tema, ¿dentro de qué modelo se aprende y se reproduce la violencia en el fútbol?', o: ['Uno patriarcal y machista', 'Uno individual y psicológico', 'Uno biológico y hereditario', 'Uno económico y de mercado'], e: 'Es la idea clave del tema: se aprende y se reproduce dentro de un modelo patriarcal y machista.', f: 'La violencia se aprende y se reproduce culturalmente, dentro de un modelo patriarcal y machista: por eso se puede prevenir.', t: 'violencia-en-el-futbol' },

  // ── Diversidad sexual ──
  { p: '¿Qué norma de 1946 excluía del voto a las personas homosexuales en la provincia de Buenos Aires?', o: ['La Ley 5.109', 'La Ley 11.019', 'La Ley 14.783', 'La Ley 26.791'], e: 'La Ley Electoral 5.109, promulgada por Domingo Mercante. La 11.019 (1990) derogó esa exclusión; la 14.783 es el cupo laboral travesti trans y la 26.791 agravó los crímenes de odio.', f: '1946: la Ley Electoral 5.109 de la provincia de Buenos Aires excluía del voto a las personas homosexuales “por razones de indignidad”.', t: 'diversidad-sexual' },
  { p: '¿En qué año se derogó la exclusión del voto de las personas homosexuales en Buenos Aires?', o: ['1990', '1951', '2003', '2010'], e: 'En 1990, con la Ley 11.019. 1951 es la enmienda al Código de Justicia Militar.', f: 'Esa prohibición se derogó recién en 1990', t: 'diversidad-sexual' },
  { p: '¿Qué jurisdicciones establecieron en 2003 la unión civil con independencia del sexo?', o: ['La Ciudad de Buenos Aires y Río Negro', 'La provincia de Buenos Aires y Córdoba', 'Santa Fe y la Ciudad de Buenos Aires', 'Río Negro y la provincia de Neuquén'], e: 'La Ciudad de Buenos Aires y Río Negro, en 2003.', f: '2003: la Ciudad de Buenos Aires y Río Negro crean la unión civil para parejas de cualquier sexo.', t: 'diversidad-sexual' },
  { p: '¿Qué modificó la Ley 26.791 (2012)?', o: ['El art. 80 inc. 4 del Código Penal', 'El Código Civil y Comercial de 2015', 'La Ley Electoral 5.109 bonaerense', 'El art. 2 de la Ley 26.485'], e: 'Agravó con prisión perpetua los crímenes de odio por orientación sexual, identidad de género o su expresión.', f: 'Agrava con prisión perpetua los asesinatos por odio a la orientación sexual, la identidad de género o su expresión (Código Penal, art. 80, inc. 4).', t: 'diversidad-sexual' },
  { p: '¿Qué estableció el Decreto 214/2006?', o: ['Prohibir discriminar por orientación en el empleo público', 'Permitir el cambio de nombre en el DNI de las personas trans', 'Fijar un cupo laboral travesti trans en la provincia', 'Reconocer la unión civil sin importar el sexo'], e: 'Es el convenio colectivo de la Administración Pública Nacional: prohíbe la discriminación laboral por orientación sexual.', f: '2006: el convenio colectivo de la Administración Pública Nacional (Decreto 214/2006) prohíbe la discriminación laboral por orientación sexual.', t: 'diversidad-sexual' },
  { p: 'Según el Observatorio Nacional de Crímenes de Odio LGBT+, ¿cuántos crímenes de odio hubo en la Argentina en 2025?', o: ['227', '200', '140', '346'], e: '227, un 62 % más que en 2024, cuando hubo 140. 200 son las víctimas de femicidio de 2025.', f: 'Según el Observatorio Nacional de Crímenes de Odio LGBT+, en 2025 hubo 227 crímenes de odio contra personas LGBTI+ en la Argentina, un 62 % más que en 2024.', t: 'diversidad-sexual' },
  { p: '¿Qué norma de 2015 igualó el acceso de parejas del mismo o distinto sexo a las figuras legales?', o: ['El Código Civil y Comercial', 'El Código Penal', 'La Ley de Identidad de Género', 'La Ley Diana Sacayán'], e: 'El nuevo Código Civil y Comercial. La Ley Diana Sacayán (14.783) también es de 2015, pero fija un cupo laboral.', f: '2015: el nuevo Código Civil y Comercial iguala a las parejas del mismo o de distinto sexo en todas las figuras legales.', t: 'diversidad-sexual' },
  { p: 'Según el art. 2 de la Ley 26.743, la identidad de género incluye…', o: ['La vivencia personal del cuerpo', 'El sexo que figura en el acta', 'La orientación sexual declarada', 'La opinión de un profesional'], e: 'Es la vivencia interna e individual del género, que puede corresponder o no con el sexo asignado, “incluyendo la vivencia personal del cuerpo”.', f: 'La Ley 26.743 define la identidad de género como “la vivencia interna e individual del género tal como cada persona la siente, la cual puede corresponder o no con el sexo asignado al momento del nacimiento”.', t: 'diversidad-sexual' },

  // ── Entendimiento de la ira ──
  { p: 'Según la guía, ¿por qué en familias disfuncionales la ira “sirve” para cambiar a los demás?', o: ['Porque se aprende a usarla para extorsionar', 'Porque reduce el estrés de toda la familia', 'Porque ayuda a expresar el dolor emocional', 'Porque los demás se vuelven inmunes a ella'], e: 'Se aprende a usarla para extorsionar; a la larga, los demás se alejan. Volverse inmunes es lo que pasa con quien grita para captar atención.', t: 'entendimiento-de-la-ira' },
  { p: 'Según la guía, ¿qué riesgos para la salud trae vivir el enojo con demasiada intensidad por períodos largos?', o: ['Hipertensión, cardiopatías y menos defensas', 'Diabetes, obesidad y colesterol alto', 'Asma, alergias y problemas de la piel', 'Osteoporosis, artrosis y dolor de espalda'], e: 'La presión y el ritmo cardíaco elevados aumentan el riesgo de hipertensión y cardiopatías, y reducen la eficiencia del sistema inmunológico.', t: 'entendimiento-de-la-ira' },
  { p: 'Según la guía, ¿cuáles son los dos componentes de “cómo nos enfadamos”?', o: ['Dolor y pensamientos desencadenantes', 'Intensificación y explosión del enojo', 'Acontecimiento activador y creencia', 'Tensión acumulada y período violento'], e: 'Una experiencia de dolor, físico o emocional, y pensamientos que nos hacen sentir víctimas de un daño deliberado. Las otras opciones son del ciclo de agresión, del ABC de Ellis y del ciclo de Walker.', t: 'entendimiento-de-la-ira' },
  { p: 'En el mito “hay que ser agresivo para conseguir lo que se quiere”, ¿con qué se confunde la agresión?', o: ['Con la asertividad', 'Con la negociación', 'Con la pasividad', 'Con la empatía'], e: 'La agresión busca dominar, intimidar o dañar; la asertividad expresa el enojo con respeto, sin culpar ni amenazar.', t: 'entendimiento-de-la-ira' },
  { p: 'Cuando la ira funciona como defensa, ¿qué bloquea según la guía?', o: ['Sentimientos que señalan lo que necesitamos', 'Recuerdos dolorosos de la primera infancia', 'Respuestas del complejo reptiliano', 'Pensamientos automáticos de culpa'], e: 'Bloquea sentimientos (miedo, pérdida, culpa, vergüenza, rechazo) que serían señales de lo que necesitamos hacer o dejar de hacer.', t: 'entendimiento-de-la-ira' },
  { p: 'Según la guía, ¿cómo se aprende la forma de expresar el enojo?', o: ['Observando a la familia y los amigos', 'A través de la herencia de los padres', 'Con la maduración del cerebro', 'Según el carácter con el que se nace'], e: 'Es una conducta aprendida por observación; por eso pueden aprenderse formas más apropiadas.', t: 'entendimiento-de-la-ira' },

  // ── El cerebro y las emociones ──
  { p: 'En el modelo de MacLean, ¿qué estructuras forman el complejo reptiliano?', o: ['Ganglios basales, tronco y cerebelo', 'Hipocampo, amígdala y tálamo', 'Lóbulos frontal, parietal y temporal', 'Corteza visual, auditiva y motora'], e: 'Ganglios basales, tronco del encéfalo y cerebelo: la estructura más primitiva, encargada de la supervivencia inmediata.', t: 'cerebro-y-emociones' },
  { p: 'Según la guía, ¿hace cuánto tiempo, como mínimo, comenzó la evolución humana?', o: ['6 millones de años', '600.000 años', '60 millones de años', '200.000 años'], e: 'Hace al menos 6 millones de años, cuando una población de primates africanos se dividió en dos linajes.', t: 'cerebro-y-emociones' },
  { p: '¿Qué plantean hoy las neurociencias sobre la evolución del cerebro, según la guía?', o: ['Que no fue escalonada', 'Que fue en tres etapas', 'Que culminó en la neocorteza', 'Que empezó por el sistema límbico'], e: 'La evolución no fue escalonada, e importa más cómo se conectan las partes que la función de cada una.', t: 'cerebro-y-emociones' },
  { p: '¿Cuántas preguntas propone la guía para analizar una situación emocional?', o: ['Seis', 'Tres', 'Cuatro', 'Ocho'], e: 'Qué pasó, por qué creés que ocurrió, cómo te hizo sentir, qué querías hacer, qué hiciste y cómo te afectó después.', t: 'cerebro-y-emociones' },
  { p: '¿Con qué se cierra el ejercicio de cambio de enfoque?', o: ['Con tres a cinco respiraciones lentas', 'Repitiendo diez veces una palabra clave', 'Con un registro en el diario de pensamientos', 'Ubicando la emoción en la escala del enojo'], e: 'Se termina en el tacto, tocando un objeto, con tres a cinco respiraciones lentas y profundas.', t: 'cerebro-y-emociones' },

  // ── Abordaje emocional (IFS) ──
  { p: '¿Cómo llaman otras teorías a lo que el modelo IFS denomina “partes” o subpersonalidades?', o: ['Mecanismos defensivos', 'Pensamientos automáticos', 'Emociones secundarias', 'Estilos de personalidad'], e: 'Lo que otras teorías llaman mecanismos defensivos, el IFS lo trata como partes con sentimientos, creencias y recuerdos propios.', t: 'abordaje-emocional-ifs' },
  { p: 'Según el modelo IFS, ¿cuáles son las funciones del Yo?', o: ['Conexión, curiosidad, compasión y sosiego', 'Vigilancia, cautela, suspicacia y control', 'Control de reglas, normas y deberes', 'Distracción, crítica, agrado y cuidado'], e: 'Conectar con los demás, tener curiosidad sin criticar ni juzgar, ser compasivo y mantenerse sosegado. Las otras son la estrategia del estilo paranoide, la del obsesivo-compulsivo y los mecanismos de los protectores.', t: 'abordaje-emocional-ifs' },
  { p: 'En el modelo IFS, ¿qué mecanismo de los protectores pone el cuidado de los demás como lo más importante?', o: ['Cuidar a otros', 'Distraer del dolor', 'Criticar para proteger', 'Volverse encantador'], e: 'Los cuatro mecanismos son: distraer del dolor, criticar para proteger, criticar para mejorar la autoestima (volverse encantador) y cuidar a otros.', t: 'abordaje-emocional-ifs' },
  { p: 'En el modelo IFS, ¿qué cierra el trabajo con los exiliados?', o: ['La ceremonia de descarga', 'La reparentalización', 'La separación del protector', 'El centrado del Yo'], e: 'La ceremonia de descarga, en la que el exiliado libera su carga. La reparentalización viene antes.', t: 'abordaje-emocional-ifs' },
  { p: 'En la ceremonia de descarga del modelo IFS, ¿a qué se le entrega la carga, en la imaginación?', o: ['A un elemento de la naturaleza', 'A un protector de su confianza', 'A una figura de autoridad', 'A otra parte del sistema'], e: 'Aire, luz, agua, fuego o tierra: algo potente y primordial que se la lleva o la transforma.', t: 'abordaje-emocional-ifs' },
  { p: 'En el modelo IFS, ¿en qué tres planos se examina con qué parte trabajar?', o: ['Sentimientos, cuerpo y pensamientos', 'Pasado, presente y futuro', 'Familia, pareja, amigos y trabajo', 'Protectores, exiliados y Yo'], e: 'Se miran los sentimientos, las sensaciones corporales y los pensamientos para encontrar la parte con un rol extremo.', t: 'abordaje-emocional-ifs' },

  // ── Pensamientos automáticos ──
  { p: '¿Qué autor trabajó ideas cercanas a los pensamientos automáticos desde la terapia racional emotiva?', o: ['Albert Ellis', 'Aaron Beck', 'Marsha Linehan', 'Richard Schwartz'], e: 'Ellis, desde la terapia racional emotiva. El concepto de pensamientos automáticos se asocia a la terapia cognitiva de Beck.', t: 'pensamientos-automaticos' },
  { p: '¿Cuántas características de los pensamientos automáticos enumera la guía?', o: ['Nueve', 'Cinco', 'Siete', 'Doce'], e: 'Nueve: específicos, taquigráficos, creídos, espontáneos, con “debería”, dramatizadores, difíciles de desviar, aprendidos e idiosincráticos.', t: 'pensamientos-automaticos' },
  { p: 'Según la guía, ¿cómo construye la visión de túnel alguien que está deprimido?', o: ['Menospreciándose y pensando en las pérdidas', 'Manteniendo la atención en el peligro', 'Concentrándose en la injusticia ajena', 'Completando la frase taquigráfica hasta su idea'], e: 'Con depresión, la atención se fija en el menosprecio propio y las pérdidas; con ansiedad, en el peligro; con cólera, en la injusticia y la maldad de los demás. Completar la frase taquigráfica es, en cambio, una técnica para reconocer los pensamientos.', t: 'pensamientos-automaticos' },
  { p: 'Según la guía, ¿cómo construye la visión de túnel alguien que está colérico?', o: ['Concentrándose en la injusticia ajena', 'Menospreciándose y pensando en las pérdidas', 'Manteniendo la atención en el peligro', 'Repasando la escena en cámara lenta'], e: 'Se concentra en la injusticia y la maldad de los demás. Repasar la escena en cámara lenta es, en cambio, una técnica para reconocer los pensamientos.', t: 'pensamientos-automaticos' },
  { p: '¿Qué columnas tiene el diario de pensamientos que propone la guía?', o: ['Hora, emoción, situación, pensamiento y %', 'Fecha, lugar, persona, conflicto y solución', 'Acontecimiento, creencia y consecuencia', 'Señal, intensidad, explosión y después'], e: 'El porcentaje es cuánto se cree el pensamiento: antes y después de la tormenta emocional. La tercera opción es el ABC de Ellis.', t: 'pensamientos-automaticos' },
  { p: '¿Qué dos técnicas propone la guía para reconocer los pensamientos automáticos?', o: ['Repasar la escena y desarrollar la frase', 'Respirar profundo y repetir una palabra', 'Medir el enojo y alejarse de la escena', 'Escribir el ABC y discutir la creencia'], e: 'Reconstruir la situación en cámara lenta y desarrollar la frase taquigráfica hasta la idea original.', t: 'pensamientos-automaticos' },

  // ── Distorsiones cognitivas ──
  { p: '¿En qué libro de 1979 Beck y colaboradores desarrollaron la terapia cognitiva de la depresión?', o: ['Cognitive Therapy of Depression', 'Cognitive Therapy and the Emotional Disorders', 'A Guide to Rational Living', 'Progressive Relaxation'], e: 'Beck, Rush, Shaw y Emery (1979). El de 1976 es Cognitive Therapy and the Emotional Disorders.', t: 'distorsiones-cognitivas' },
  { p: '¿De qué autores es el nombre "filtraje"?', o: ['McKay, Davis y Fanning', 'Beck, Rush, Shaw y Emery', 'Ellis y Harper', 'Jacobson y Davis'], e: 'McKay, Davis y Fanning, en Técnicas cognitivas para el tratamiento del estrés.', t: 'distorsiones-cognitivas' },
  { p: '¿Qué distorsión describen McKay, Davis y Fanning como esperar que el sacrificio sea recompensado?', o: ['Falacia de recompensa divina', 'Conclusión arbitraria', 'Pensamiento dicotómico', 'Generalización excesiva'], e: 'Esperar la recompensa como si alguien llevara la cuenta; si no llega, aparecen la amargura y el resentimiento.', t: 'distorsiones-cognitivas' },
  { p: '¿Por qué la guía dice que una distorsión "no es una mentira"?', o: ['Porque se vive como un hecho, aunque no lo sea', 'Porque siempre describe la realidad', 'Porque se dice a propósito para convencer', 'Porque solo aparece en la depresión'], e: 'Es una interpretación automática que se vive como un hecho, aunque no se ajuste a lo que pasó.', t: 'distorsiones-cognitivas' },
  { p: '¿Con qué herramienta de otro tema se complementa el registro de distorsiones?', o: ['El diario de pensamientos', 'El iceberg de la violencia', 'El ciclo de la violencia', 'El mensaje asertivo'], e: 'Con el diario de pensamientos (Pensamientos automáticos) y con el ABC de Pensar correctamente.', t: 'distorsiones-cognitivas' },
  { p: '¿En qué situaciones son más frecuentes las distorsiones, según la guía?', o: ['Con estrés, ansiedad o depresión', 'Al tomar decisiones rápidas', 'Al hablar con desconocidos', 'Durante la infancia'], e: 'Son más frecuentes con estrés, ansiedad o depresión.', t: 'distorsiones-cognitivas' },

  // ── Pensar correctamente ──
  { p: 'En el ABC de Ellis, ¿qué palabra inglesa da nombre a la B?', o: ['Belief: la creencia', 'Behavior: la conducta', 'Body: el cuerpo', 'Background: la historia'], e: 'B es el sistema de creencias (belief), lo que realmente causa la consecuencia emocional.', t: 'pensar-correctamente' },
  { p: '¿Cuántos mitos irracionales enumera la guía?', o: ['Catorce', 'Diez', 'Doce', 'Nueve'], e: 'Catorce, desde “todo el mundo tiene que querernos” hasta “yo sé lo que es mejor para los demás”.', t: 'pensar-correctamente' },
  { p: 'Frente al mito “el pasado determina la conducta presente”, la guía sostiene que…', o: ['Cambiar lo aprendido es difícil pero posible', 'El pasado no influye en lo que hacemos hoy', 'Lo aprendido de chicos ya no se modifica', 'Conviene olvidar el pasado por completo'], e: 'Hay que aprender del pasado sin apegarse a él: cambiar es difícil pero no imposible.', t: 'pensar-correctamente' },
  { p: 'Frente al mito “necesitamos a alguien más fuerte en quien apoyarnos”, la guía sostiene que…', o: ['Cierta dependencia es normal, pero no exagerada', 'Toda dependencia es un error que hay que evitar', 'Conviene buscar siempre a alguien más fuerte', 'Depender mucho da seguridad a los dos'], e: 'La dependencia exagerada vuelve inseguros a ambos: la vida no depende de otro.', t: 'pensar-correctamente' },
  { p: '“Debo actuar bien y recibir aprobación, o soy indigno de ser querido.” ¿A qué categoría de Ellis pertenece?', o: ['Al pensamiento sobre uno mismo', 'Al pensamiento sobre los demás', 'Al pensamiento sobre la vida', 'Al pensamiento sobre el futuro'], e: 'Las tres categorías son sobre uno mismo, sobre los demás y sobre la vida.', t: 'pensar-correctamente' },
  { p: 'Frente al mito “tenemos derecho a una vida sin dolor”, ¿qué propone la guía?', o: ['Mejorar lo posible y aceptar lo inevitable', 'Evitar cualquier situación que pueda doler', 'Exigir que los demás nos eviten el dolor', 'Preocuparse hasta que el peligro pase'], e: 'La adversidad es parte de la vida. No confundir con el derecho a una vida libre de violencia, que sí está reconocido (Belém do Pará, art. 3; Ley 26.485). Preocuparse hasta que pase es otro de los mitos.', t: 'pensar-correctamente' },

  // ── Teoría del apego ──
  { p: '¿En qué años vivió John Bowlby?', o: ['1907-1990', '1856-1939', '1913-1999', '1920-2007'], e: 'Nació en 1907 y murió en 1990.', t: 'teoria-del-apego' },
  { p: '¿Quién describió los estilos de apego seguro, ambivalente y evitativo?', o: ['Mary Ainsworth (1978)', 'John Bowlby (1969)', 'Peter Fonagy (2004)', 'Main y Solomon (1990)'], e: 'La psicóloga Mary Ainsworth, colaboradora de Bowlby, en Patterns of Attachment (1978).', t: 'teoria-del-apego' },
  { p: '¿Quiénes sumaron el estilo de apego desorganizado?', o: ['Main y Solomon (1990)', 'Ainsworth y Blehar (1978)', 'Lorenz y Harlow', 'Sheinberg y True (2008)'], e: 'Mary Main y Judith Solomon (1990).', t: 'teoria-del-apego' },
  { p: '¿Qué otro nombre recibe el apego ambivalente?', o: ['Resistente', 'Desorganizado', 'Evitativo', 'Dependiente'], e: 'Ambivalente o resistente: es la nomenclatura de Ainsworth.', t: 'teoria-del-apego' },
  { p: '¿Qué autor sostiene que aprendemos a regular las emociones en el vínculo con quien nos cuida?', o: ['Fonagy (2004)', 'Beck (1979)', 'Ellis (1962)', 'Firth (1951)'], e: 'Fonagy, en Teoría del apego y psicoanálisis (2004).', t: 'teoria-del-apego' },
  { p: '¿Cuáles son las tres claves de la teoría del apego que presenta la guía?', o: ['Apoyo, confianza y accesibilidad', 'Seguridad, libertad y límites', 'Hechos, sentimientos y pedido', 'Acontecimiento, creencia y consecuencia'], e: 'Apoyo, confianza y accesibilidad. Las otras son el manejo de los celos, el mensaje asertivo y el ABC de Ellis.', t: 'teoria-del-apego' },

  // ── Personalidad ──
  { p: '¿Qué autores describieron la paranoia como un conjunto de estrategias para prevenir o reducir la vergüenza?', o: ['Colby y Faught', 'Beck y Freeman', 'Ellis y Beck', 'Real y Coontz'], e: 'Colby y Faught (1981): de fondo hay una creencia de ser inadecuado e insuficiente.', t: 'personalidad' },
  { p: '¿Qué estilo de personalidad valora la independencia, decide solo y ve a los demás como intrusivos?', o: ['El esquizoide', 'El narcisista', 'El de evitación', 'El paranoide'], e: 'El esquizoide se ve autosuficiente; su amenaza es el acercamiento excesivo y su estrategia, mantener la distancia.', t: 'personalidad' },
  { p: '¿Qué estilo de personalidad se ve socialmente inepto y suprime a cualquier costo los sentimientos desagradables?', o: ['El de evitación', 'El esquizoide', 'El de dependencia', 'El paranoide'], e: 'Teme ser descubierto como un fraude o humillado; puede suprimir el malestar con bebida o drogas.', t: 'personalidad' },
  { p: 'En el estilo narcisista, ¿qué afecto aparece cuando no recibe la admiración que cree merecer?', o: ['Cólera', 'Euforia', 'Disforia', 'Remordimiento'], e: 'Cólera; y depresión si sus estrategias fallan. La disforia es del estilo de evitación y el remordimiento, del obsesivo-compulsivo.', t: 'personalidad' },
  { p: '¿Qué estrategia usa el estilo narcisista?', o: ['Manipular para reforzar su estatus', 'Vigilar con cautela y suspicacia', 'Subordinarse para agradar al otro', 'Regirse por normas y deberes'], e: 'Manipula para reforzar su estatus y ampliar su dominio personal. Las otras son estrategias de los estilos paranoide, por dependencia y obsesivo-compulsivo.', t: 'personalidad' },
  { p: 'Según la guía, ¿en qué tipo de ambiente suele haberse criado la persona con estilo obsesivo-compulsivo?', o: ['Rígido y controlador', 'Caótico y desorganizado', 'Sobreprotector y permisivo', 'Distante y solitario'], e: 'Rígido y controlador; además suele no tener relaciones estrechas ni actividades de tiempo libre.', t: 'personalidad' },

  // ── El duelo ──
  { p: '¿En qué obra de 1980 trató Bowlby la pérdida?', o: ['La pérdida afectiva', 'El dolor invisible de la infancia', 'Terapia cognitiva de la depresión', 'Técnicas de autocontrol emocional'], e: 'La pérdida afectiva: tristeza y depresión es el volumen 3 de Attachment and Loss (1980).', t: 'duelo' },
  { p: 'Según el DSM-5-TR, ¿cuánto deben persistir los síntomas en adultos para hablar de trastorno de duelo prolongado?', o: ['Al menos 12 meses', 'Al menos 6 meses', 'Al menos 1 mes', 'Al menos 2 años'], e: 'Al menos 12 meses en adultos (APA, 2022). La CIE-11 habla de al menos 6 meses.', t: 'duelo' },
  { p: 'Según la CIE-11 de la OMS, ¿cuánto deben persistir los síntomas para hablar de trastorno de duelo prolongado?', o: ['Al menos 6 meses', 'Al menos 12 meses', 'Al menos 3 meses', 'Al menos 2 años'], e: 'Al menos 6 meses, teniendo en cuenta lo que se espera en cada cultura.', t: 'duelo' },
  { p: '¿Qué dos formas de duelo complicado describió Bowlby?', o: ['Duelo crónico y ausencia de duelo', 'Duelo agudo y duelo anticipado', 'Duelo normal y duelo prolongado', 'Duelo infantil y duelo adulto'], e: 'El duelo crónico, con emociones muy intensas que no mejoran, y la ausencia de duelo, cuando la pérdida parece no afectar.', t: 'duelo' },
  { p: '¿Qué antropólogo señaló que los rituales funerarios benefician a quienes quedan?', o: ['Raymond Firth', 'Robert Trivers', 'Konrad Lorenz', 'Pablo Alabarces'], e: 'Raymond Firth (1951), citado por Bowlby.', t: 'duelo' },
  { p: '¿Qué concepto de Trivers (1971) explica la ayuda mutua en los rituales?', o: ['El altruismo recíproco', 'La socialización diferencial', 'El trauma relacional', 'La impronta'], e: 'Hoy ayudo yo y mañana, si lo necesito, me ayudan a mí.', t: 'duelo' },

  // ── Habilidades interpersonales ──
  { p: 'Además de la OMS, ¿qué autora se cita en el tema de habilidades interpersonales?', o: ['Marsha Linehan', 'Lenore Walker', 'Lori Heise', 'Kali Holloway'], e: 'Marsha Linehan (1993), por sus habilidades de efectividad interpersonal de la terapia dialéctico conductual (DBT).', t: 'habilidades-interpersonales' },
  { p: 'Según la guía, ¿qué habilidades se consideran “de pensamiento”?', o: ['Solución de problemas y creatividad', 'Comunicación, asertividad y empatía', 'Prestar atención y parafrasear al otro', 'Saber pedir, saber decir no y negociar'], e: 'Solución de problemas y pensamiento creativo. La comunicación, la asertividad y la empatía son, en cambio, habilidades sociales; las otras dos opciones son claves de comunicación y habilidades interpersonales.', t: 'habilidades-interpersonales' },
  { p: 'Según la guía, ¿qué dos equilibrios necesita una relación?', o: ['“Yo quiero – los otros quieren” y “quiero – debería”', '“Yo quiero – yo debería” y “los otros quieren – deben”', '“Hablar – callar” y “pedir – dar”', '“Pasivo – agresivo” y “asertivo – sumiso”'], e: 'Si falta el primero, la relación se vuelve inestable; si falta el segundo, genera resentimiento o se vuelve una carga.', t: 'habilidades-interpersonales' },
  { p: 'Según la guía, ¿por qué la asertividad es especialmente importante en niñas, niños y adolescentes?', o: ['Por la presión del grupo', 'Por la autoridad adulta', 'Por las exigencias escolares', 'Por la competencia deportiva'], e: 'Decir lo que se siente o piensa de forma amable ayuda frente a la presión del grupo.', t: 'habilidades-interpersonales' },
  { p: 'En el esquema para resolver problemas, ¿qué se descarta al elegir la mejor opción?', o: ['Las opciones no factibles', 'Las opciones más costosas', 'Las propuestas de los demás', 'Las desventajas de cada una'], e: 'Se elige la que más beneficios aporta, descartando las que no se pueden llevar a cabo.', t: 'habilidades-interpersonales' },

  // ── Límites y negociación ──
  { p: '¿Cuántos pasos tiene la negociación según la guía?', o: ['Seis', 'Tres', 'Cuatro', 'Cinco'], e: 'Saber qué se quiere, expresarlo en conductas, escuchar, proponer, pedir contrapropuesta y llegar a un compromiso. Las pautas para poner límites son tres.', t: 'limites-y-negociacion' },
  { p: '¿Cuántas pautas básicas da la guía para establecer límites?', o: ['Tres', 'Seis', 'Cinco', 'Dos'], e: 'Reconocer las necesidades del otro, expresar la propia posición y decir “no”. Los pasos de la negociación son seis.', t: 'limites-y-negociacion' },
  { p: 'En la negociación, ¿por qué “quiero ser feliz” no sirve como primer paso?', o: ['Porque es demasiado vago', 'Porque es demasiado egoísta', 'Porque es imposible de lograr', 'Porque no incluye al otro'], e: 'El primer paso pide saber qué se quiere, lo más específico posible.', t: 'limites-y-negociacion' },
  { p: 'Según la guía, ¿qué requiere el paso de “realizar una propuesta”?', o: ['Creatividad y flexibilidad', 'Firmeza y rapidez', 'Paciencia y silencio', 'Autoridad y buenos argumentos'], e: 'Hay que considerar qué necesita y qué gana la otra persona.', t: 'limites-y-negociacion' },
  { p: 'Según la guía, ¿qué transmite pedir disculpas al poner un límite?', o: ['Que no nos creemos con derecho a cuidarnos', 'Que el límite es firme y no se discute', 'Que respetamos mucho los tiempos del otro', 'Que estamos dispuestos a negociar el resto'], e: 'Además invita al otro a presionar más.', t: 'limites-y-negociacion' },

  // ── Nuevas familias ──
  { p: '¿En qué año se sancionó la Ley 23.515 de divorcio vincular?', o: ['1987', '1994', '2010', '2015'], e: 'En 1987. 2010 es la Ley 26.618 de matrimonio igualitario y 2015, el Código Civil y Comercial.', t: 'nuevas-familias' },
  { p: '¿En qué año se sancionó la Ley 26.618 de matrimonio igualitario?', o: ['2010', '1987', '2006', '2015'], e: 'En 2010.', t: 'nuevas-familias' },
  { p: '¿Cómo llama el Código Civil y Comercial a la obligación de criar y proteger que siguen teniendo ambos progenitores?', o: ['Responsabilidad parental', 'Patria potestad', 'Régimen de visitas', 'Tenencia compartida'], e: 'Responsabilidad parental: ambos progenitores siguen siendo responsables de criar y proteger, más allá de la separación.', t: 'nuevas-familias' },
  { p: '¿Qué autoras escribieron Maltrato al menor: el lado oculto de la escena familiar?', o: ['Grosman y Mesterman', 'Lagarde y Herrera', 'Sheinberg y True', 'Main y Solomon'], e: 'Cecilia Grosman y Silvia Mesterman.', t: 'nuevas-familias' },
  { p: 'Antes de la ley de divorcio de 1987, ¿qué se creía de los hijos de padres separados?', o: ['Que se volverían enfermos o delincuentes', 'Que crecerían con más autonomía', 'Que debían quedarse con la madre', 'Que el daño era solo económico'], e: 'Se creía que la separación los volvía enfermos o delincuentes. Hoy se sabe que duele, pero no enferma por sí sola.', t: 'nuevas-familias' },
  { p: '¿Qué frase resume lo que hoy se sabe sobre la separación de los padres?', o: ['Doloroso no es lo mismo que enfermante', 'Toda separación deja un trauma', 'No deja marcas si hay acuerdo', 'Afecta sobre todo a los más chicos'], e: 'Una separación puede doler y dejar marcas, pero no enferma por sí misma.', t: 'nuevas-familias' },

  // ── Relajación avanzada ──
  { p: '¿Qué autores se citan en el tema de relajación avanzada?', o: ['Jacobson y Davis', 'Beck y Freeman', 'Colby y Faught', 'Linehan y Schwartz'], e: 'E. Jacobson (Progressive Relaxation, 1938) y Davis, McKay y Eshelman (Técnicas de autocontrol emocional).', t: 'relajacion-avanzada' },
  { p: 'En la respiración con escenas de estrés, ¿cómo se visualiza la segunda escena la primera vez?', o: ['Sin respirar hondo, para medir el estrés', 'Con la palabra clave en cada exhalación', 'Con respiración profunda en cada parte', 'Tensando los músculos uno por uno'], e: 'Primero sin respiración profunda, registrando el estrés; después se repite al menos dos veces respirando con el diafragma.', t: 'relajacion-avanzada' },
  { p: 'En la respiración con escenas de estrés, ¿cuántas escenas se eligen?', o: ['Dos', 'Tres', 'Cinco', 'Una'], e: 'Dos escenas, cada una dividida en tres partes.', t: 'relajacion-avanzada' },
  { p: 'En la respiración con escenas de estrés, ¿cuántas veces se repite la visualización de la primera escena?', o: ['Dos o tres veces', 'Diez veces seguidas', 'Una sola vez', 'Cinco o seis veces'], e: 'Se repite dos o tres veces, respirando con el diafragma al final de cada parte.', t: 'relajacion-avanzada' },
  { p: '¿Qué técnica de relajación usaba el aumento de la tensión muscular?', o: ['La relajación progresiva', 'La relajación con palabra clave', 'El cambio de enfoque', 'La respiración diafragmática'], e: 'La relajación progresiva tensaba y aflojaba; la relajación sin tensión elimina ese paso.', t: 'relajacion-avanzada' },
];
